add('lung-rads','baseline-solid',
 L('Bei der ersten LDCT im Screening liegt ein glattrandiger solider Rundherd mit 7,0 mm mittlerem Durchmesser vor. Keine weiteren suspekten Merkmale. Welche Einordnung passt zu Lung-RADS v2022?', 'Baseline screening LDCT shows a smooth solid nodule with a mean diameter of 7.0 mm and no additional suspicious features. Which Lung-RADS v2022 assessment fits?', 'در LDCT اولیهٔ غربالگری، ندول جامد با حاشیهٔ صاف و قطر میانگین ۷٫۰ میلی‌متر و بدون ویژگی مشکوک دیگر دیده می‌شود. کدام ارزیابی Lung-RADS نسخهٔ ۲۰۲۲ مناسب است؟'),
 [L('Kategorie 2 · LDCT in 12 Monaten','Category 2 · LDCT in 12 months','دستهٔ ۲ · LDCT در ۱۲ ماه'), L('Kategorie 3 · LDCT in 6 Monaten','Category 3 · LDCT in 6 months','دستهٔ ۳ · LDCT در ۶ ماه'), L('Kategorie 4A · LDCT in 3 Monaten','Category 4A · LDCT in 3 months','دستهٔ 4A · LDCT در ۳ ماه'), L('Kategorie 4B · diagnostische Abklärung','Category 4B · diagnostic evaluation','دستهٔ 4B · بررسی تشخیصی')], 'B',
 L('Ein solider Baseline-Nodulus von 6 bis unter 8 mm fällt ohne höhergradige Merkmale in Kategorie 3. Der reguläre nächste Schritt ist eine LDCT nach sechs Monaten.', 'A baseline solid nodule from 6 to under 8 mm without higher-category features is category 3. The standard next step is six-month LDCT.', 'ندول جامد اولیهٔ ۶ تا کمتر از ۸ میلی‌متر بدون ویژگی مربوط به دستهٔ بالاتر، در دستهٔ ۳ قرار می‌گیرد. گام معمول بعدی LDCT شش‌ماهه است.'),
 {A:L('Die Baseline-Grenze für Kategorie 2 liegt bei unter 6 mm; der beschriebene Nodulus ist größer.', 'The relevant category 2 baseline threshold is under 6 mm; this nodule exceeds it.', 'آستانهٔ اولیهٔ دستهٔ ۲ کمتر از ۶ میلی‌متر است؛ این ندول از آن بزرگ‌تر است.'),C:L('Bei einem soliden Baseline-Nodulus beginnt 4A ohne weitere Merkmale erst bei 8 mm.', 'For a baseline solid nodule without additional features, 4A begins at 8 mm.', 'برای ندول جامد اولیه بدون ویژگی اضافی، 4A از ۸ میلی‌متر آغاز می‌شود.'),D:L('7 mm allein erfüllt nicht die Baseline-Größenschwelle für 4B.', 'A 7 mm baseline nodule alone does not meet the size threshold for 4B.', 'اندازهٔ ۷ میلی‌متری در بررسی اولیه به‌تنهایی به آستانهٔ اندازهٔ 4B نمی‌رسد.')}, RADS,
 L('Warum muss bei einem 7-mm-Nodulus im Lung-RADS-Bericht „baseline“ oder „neu“ stehen?', 'Why must a Lung-RADS report specify whether a 7 mm nodule is baseline or new?', 'چرا در گزارش Lung-RADS برای ندول ۷ میلی‌متری باید اولیه یا جدید بودن مشخص شود؟'),
 L('Die Schwellen unterscheiden sich: ein solider Baseline-Nodulus von 7 mm ist Kategorie 3, ein neuer solider Nodulus dieser Größe Kategorie 4A, sofern keine höhergradigen Merkmale vorliegen.', 'The thresholds differ: a 7 mm baseline solid nodule is category 3, while a new solid nodule of that size is category 4A, assuming no higher-category features.', 'آستانه‌ها متفاوت‌اند: ندول جامد اولیهٔ ۷ میلی‌متری دستهٔ ۳ و ندول جامد جدید با همین اندازه دستهٔ 4A است، اگر ویژگی مربوط به دستهٔ بالاتر وجود نداشته باشد.'))

add('lung-rads','new-solid',
 L('Im jährlichen Screening ist ein neuer solider Nodulus von 7,0 mm mittlerem Durchmesser sichtbar; zuvor war er nicht vorhanden. Keine zusätzlichen suspekten Merkmale. Was folgt nach Lung-RADS v2022?', 'Annual screening reveals a new solid nodule with a mean diameter of 7.0 mm, absent previously and without additional suspicious features. What follows under Lung-RADS v2022?', 'در غربالگری سالانه ندول جامد جدید با قطر میانگین ۷٫۰ میلی‌متر دیده می‌شود؛ قبلاً وجود نداشته و ویژگی مشکوک اضافی ندارد. بر اساس Lung-RADS نسخهٔ ۲۰۲۲ گام بعدی چیست؟'),
 [L('Kategorie 3 · LDCT in 6 Monaten','Category 3 · LDCT in 6 months','دستهٔ ۳ · LDCT در ۶ ماه'),L('Kategorie 2 · jährliches Screening','Category 2 · annual screening','دستهٔ ۲ · غربالگری سالانه'),L('Kategorie 4A · LDCT in 3 Monaten','Category 4A · LDCT in 3 months','دستهٔ 4A · LDCT در ۳ ماه'),L('Kategorie 4B · diagnostische Abklärung','Category 4B · diagnostic evaluation','دستهٔ 4B · بررسی تشخیصی')], 'C',
 L('Bei einem neuen soliden Nodulus gilt bereits 6 bis unter 8 mm als 4A. Eine kurzfristige LDCT nach drei Monaten ist vorgesehen; 7 mm ist nicht die Schwelle für die PET-Erwägung bei einem soliden Anteil von mindestens 8 mm.', 'A new solid nodule from 6 to under 8 mm is 4A, with three-month LDCT. At 7 mm it does not reach the solid-component threshold of at least 8 mm for considering PET.', 'ندول جامد جدید ۶ تا کمتر از ۸ میلی‌متر دستهٔ 4A است و LDCT سه‌ماهه دارد. اندازهٔ ۷ میلی‌متری به آستانهٔ جزء جامد حداقل ۸ میلی‌متری برای بررسی PET نمی‌رسد.'),
 {A:L('Sechs Monate passen zur Kategorie 3; für neue solide Noduli gelten niedrigere Schwellen als bei Baseline.', 'Six months corresponds to category 3; new solid nodules have lower thresholds than baseline nodules.', 'شش ماه مربوط به دستهٔ ۳ است؛ ندول جامد جدید آستانه‌های پایین‌تری از ندول اولیه دارد.'),B:L('Für einen neuen soliden Nodulus liegt die Kategorie-2-Schwelle bei unter 4 mm.', 'The category 2 threshold for a new solid nodule is under 4 mm.', 'آستانهٔ دستهٔ ۲ برای ندول جامد جدید کمتر از ۴ میلی‌متر است.'),D:L('Die 4B-Größenschwelle für einen neuen soliden Nodulus liegt bei mindestens 8 mm; auch dann wird die Abklärung klinisch geplant.', 'The size threshold for a new solid nodule in 4B is at least 8 mm; evaluation is still tailored clinically.', 'آستانهٔ اندازهٔ ندول جامد جدید برای 4B حداقل ۸ میلی‌متر است؛ حتی در آن حالت هم بررسی بر اساس زمینهٔ بالینی برنامه‌ریزی می‌شود.')},RADS,
 L('Welches Intervall gehört zu einem neuen soliden Screening-Nodulus von 6 bis unter 8 mm ohne zusätzliche suspekte Merkmale?', 'What interval applies to a new solid screening nodule from 6 to under 8 mm without additional suspicious features?', 'فاصلهٔ پیگیری ندول جامد جدیدِ غربالگری از ۶ تا کمتر از ۸ میلی‌متر بدون ویژگی مشکوک اضافی چیست؟'),
 L('Lung-RADS v2022: Kategorie 4A und LDCT in 3 Monaten; die Baseline-Schwellen dürfen nicht übernommen werden.', 'Lung-RADS v2022: category 4A and LDCT in 3 months; do not apply baseline thresholds.', 'Lung-RADS نسخهٔ ۲۰۲۲: دستهٔ 4A و LDCT در ۳ ماه؛ آستانه‌های اولیه را به‌کار نبرید.'))

add('lung-rads','stepped-management',
 L('Ein solider Screening-Nodulus wurde als 4A eingestuft. Nach drei Monaten ist er unverändert; keine weiteren bedenklichen Befunde. Welche gestufte Weiterbetreuung sieht Lung-RADS v2022 vor?', 'A solid screening nodule was assessed as 4A. At three months it is unchanged, with no other concerning findings. Which stepped management does Lung-RADS v2022 recommend?', 'ندول جامد غربالگری در دستهٔ 4A بوده است. در سه ماه تغییری ندارد و یافتهٔ نگران‌کنندهٔ دیگری نیست. مدیریت مرحله‌ای Lung-RADS نسخهٔ ۲۰۲۲ چیست؟'),
 [L('Kategorie 2 · 12 Monate ab Erstuntersuchung','Category 2 · 12 months from baseline','دستهٔ ۲ · ۱۲ ماه از بررسی اولیه'),L('Kategorie 4B · Biopsie wegen fehlender Größenabnahme','Category 4B · biopsy because it has not decreased','دستهٔ 4B · بیوپسی به دلیل کوچک نشدن'),L('Kategorie 0 · kein Folgeintervall festlegen','Category 0 · no follow-up interval','دستهٔ ۰ · بدون تعیین فاصلهٔ پیگیری'),L('Kategorie 3 · LDCT in 6 Monaten ab aktueller Kontrolle','Category 3 · LDCT in 6 months from this examination','دستهٔ ۳ · LDCT شش ماه پس از بررسی کنونی')], 'D',
 L('Ein bei der 3-Monats-Kontrolle stabiler oder kleinerer 4A-Befund wird im gestuften Management zu Kategorie 3 mit LDCT sechs Monate nach dieser Kontrolle. Die kurze Stabilität beweist keine Benignität.', 'A 4A finding stable or smaller at three months moves to category 3 in stepped management, with LDCT six months after that examination. Brief stability does not establish benignity.', 'یافتهٔ 4A که در سه ماه ثابت یا کوچک‌تر است، در مدیریت مرحله‌ای به دستهٔ ۳ می‌رود و LDCT شش ماه پس از همان کنترل انجام می‌شود. ثبات کوتاه‌مدت خوش‌خیمی را ثابت نمی‌کند.'),
 {A:L('v2022 sieht zunächst einen weiteren Schritt über Kategorie 3 vor; nicht direkt jährliche Kontrolle.', 'v2022 first steps down through category 3 rather than returning directly to annual screening.', 'نسخهٔ ۲۰۲۲ ابتدا مرحلهٔ دستهٔ ۳ را در نظر می‌گیرد و مستقیم به غربالگری سالانه برنمی‌گردد.'),B:L('Stabilität nach drei Monaten allein begründet keine Hochstufung zu 4B.', 'Stability at three months alone does not justify escalation to 4B.', 'ثبات در سه ماه به‌تنهایی دلیل ارتقا به 4B نیست.'),C:L('Die Untersuchung ist auswertbar; Kategorie 0 bezeichnet einen anderen, unvollständigen Abklärungskontext.', 'The examination is assessable; category 0 addresses a different, incomplete evaluation context.', 'این بررسی قابل ارزیابی است؛ دستهٔ ۰ مربوط به زمینهٔ متفاوتِ ارزیابی ناکامل است.')},RADS,
 L('Was folgt in Lung-RADS v2022 auf einen bei drei Monaten stabilen 4A-Nodulus?', 'What follows a 4A nodule stable at three months in Lung-RADS v2022?', 'در Lung-RADS نسخهٔ ۲۰۲۲ پس از ثبات ندول 4A در سه ماه چه می‌شود؟'),
 L('Ohne weitere bedenkliche Befunde zunächst Kategorie 3 und LDCT sechs Monate ab dieser Kontrolle; kurze Stabilität beweist keine Benignität.', 'With no other concerning findings, step down to category 3 with LDCT six months from that examination; brief stability does not establish benignity.', 'بدون یافتهٔ نگران‌کنندهٔ دیگر، ابتدا دستهٔ ۳ و LDCT شش ماه پس از همان کنترل؛ ثبات کوتاه‌مدت خوش‌خیمی را ثابت نمی‌کند.'))

add('kardio-mrt-basics','cine-volume',
 L('Bei dilatativer Kardiomyopathie sollen LV-Volumina und Ejektionsfraktion quantifiziert werden. Welcher Datensatz ist dafür primär erforderlich?', 'In dilated cardiomyopathy, LV volumes and ejection fraction need quantification. Which dataset is primarily required?', 'در کاردیومیوپاتی اتساعی باید حجم‌های بطن چپ و کسر جهشی کمی‌سازی شوند. کدام داده در درجهٔ اول لازم است؟'),
 [L('LGE-Einzelbild in kurzer Achse','A single short-axis LGE image','یک تصویر LGE در محور کوتاه'),L('T2-gewichteter Einzelquerschnitt','A single T2-weighted slice','یک مقطع وزن‌دار T2'),L('Zeitaufgelöster Cine-Stapel mit vollständiger LV-Abdeckung','A time-resolved cine stack covering the entire LV','مجموعهٔ Cine زمان‌تفکیک‌شده با پوشش کامل بطن چپ'),L('First-Pass-Perfusion in drei Schichten','First-pass perfusion in three slices','پرفیوژن عبور اول در سه مقطع')],'C',
 L('Enddiastolische und endsystolische Konturen aus einem Cine-Stapel liefern die Volumina und daraus die EF. Eine einzelne Gewebeschicht oder Perfusionsserie ersetzt die vollständige Volumenabdeckung nicht.', 'End-diastolic and end-systolic contours from a cine stack provide volumes and hence EF. A single tissue slice or perfusion series does not replace complete volumetric coverage.', 'کانتورهای پایان دیاستول و پایان سیستول در مجموعهٔ Cine حجم‌ها و سپس EF را می‌دهند. یک مقطع بافتی یا سری پرفیوژن جای پوشش حجمی کامل را نمی‌گیرد.'),
 {A:L('LGE charakterisiert Kontrastverteilung und Narbe, nicht allein das Schlagvolumen.', 'LGE characterises contrast distribution and scar, rather than providing stroke volume by itself.', 'LGE توزیع کنتراست و اسکار را مشخص می‌کند و به‌تنهایی حجم ضربه‌ای را نمی‌دهد.'),B:L('T2 dient der Beurteilung erhöhten Wassergehalts; ein Einzelquerschnitt reicht nicht für globale LV-Volumina.', 'T2 assesses increased water content; one slice is insufficient for global LV volumes.', 'T2 برای ارزیابی افزایش آب بافت است؛ یک مقطع برای حجم کلی بطن چپ کافی نیست.'),D:L('First-Pass-Perfusion verfolgt den Kontrastbolus zur Durchblutungsbeurteilung.', 'First-pass perfusion follows the contrast bolus to assess perfusion.', 'پرفیوژن عبور اول بولوس مادهٔ حاجب را برای ارزیابی خون‌رسانی دنبال می‌کند.')},CMR,
 L('Wie berechnet sich die LV-EF aus Cine-Volumina?', 'How is LV EF calculated from cine volumes?', 'EF بطن چپ از حجم‌های Cine چگونه محاسبه می‌شود؟'),
 L('(EDV − ESV) / EDV × 100 %. Vollständige Abdeckung und konsistente Konturkonventionen sind erforderlich.', '(EDV − ESV) / EDV × 100%. Complete coverage and consistent contour conventions are required.', '(EDV − ESV) / EDV × ۱۰۰٪. پوشش کامل و روش یکنواخت ترسیم کانتور لازم است.'))

add('kardio-mrt-basics','sequence-question',
 L('Nach Troponinanstieg soll zusätzlich zur Funktion geprüft werden, ob vermehrtes myokardiales Wasser vorliegt. Welcher Baustein adressiert diese Frage direkt?', 'After a troponin rise, increased myocardial water content needs assessment in addition to function. Which component directly addresses this question?', 'پس از افزایش تروپونین، افزون بر عملکرد باید افزایش آب میوکارد بررسی شود. کدام بخش مستقیماً این پرسش را پاسخ می‌دهد؟'),
 [L('T2-gewichtete Bildgebung bzw. T2-Mapping','T2-weighted imaging or T2 mapping','تصویربرداری وزن‌دار T2 یا مپینگ T2'),L('Phasenkontrastmessung in der Aorta','Aortic phase-contrast flow imaging','اندازه‌گیری جریان فازکنتراست در آئورت'),L('Koronare MR-Angiographie','Coronary MR angiography','آنژیوگرافی MR کرونر'),L('Cine allein','Cine imaging alone','فقط Cine')],'A',
 L('T2-sensitive Verfahren unterstützen den Ödemnachweis. Ein erhöhter T2-Wert ist im klinischen und multiparametrischen Kontext zu bewerten und beweist für sich keine bestimmte Ätiologie.', 'T2-sensitive methods support oedema assessment. Elevated T2 requires clinical and multiparametric interpretation and alone does not establish a specific cause.', 'روش‌های حساس به T2 به ارزیابی ادم کمک می‌کنند. افزایش T2 باید در زمینهٔ بالینی و چندپارامتری تفسیر شود و به‌تنهایی علت مشخصی را ثابت نمی‌کند.'),
 {B:L('Phasenkontrast dient hier der Flussquantifizierung, nicht direkt dem Gewebewasser.', 'Phase contrast quantifies flow here rather than directly assessing tissue water.', 'فازکنتراست در اینجا جریان را کمی‌سازی می‌کند، نه آب بافت را به‌طور مستقیم.'),C:L('Die Koronaranatomie beantwortet die Frage nach myokardialem Wasser nicht unmittelbar.', 'Coronary anatomy does not directly answer the myocardial-water question.', 'آناتومی کرونر مستقیماً پرسش آب میوکارد را پاسخ نمی‌دهد.'),D:L('Cine zeigt Bewegung und Funktion; Ödem kann trotz erhaltener Funktion vorliegen.', 'Cine shows motion and function; oedema can occur despite preserved function.', 'Cine حرکت و عملکرد را نشان می‌دهد؛ ادم با وجود عملکرد حفظ‌شده نیز ممکن است.')},CMR,
 L('Welche klinischen Fragen trennen Cine, Perfusion, T2 und LGE?', 'Which clinical questions distinguish cine, perfusion, T2 and LGE?', 'پرسش‌های بالینی Cine، پرفیوژن، T2 و LGE چه تفاوتی دارند؟'),
 L('Cine: Bewegung/Volumina. Perfusion: Durchblutung. T2: Wasser/Ödem. LGE: Verteilung fokaler myokardialer Schädigung bzw. Narbe im Kontext.', 'Cine: motion/volumes. Perfusion: blood supply. T2: water/oedema. LGE: distribution of focal myocardial injury or scar in context.', 'Cine: حرکت/حجم. پرفیوژن: خون‌رسانی. T2: آب/ادم. LGE: توزیع آسیب کانونی یا اسکار میوکارد در زمینهٔ مربوط.'))

add('kardio-mrt-basics','lge-role',
 L('Bei stabiler LV-Dysfunktion soll eine fokale Infarktnarbe dargestellt werden. Welche Aufnahme adressiert diese Gewebefrage am direktesten?', 'In stable LV dysfunction, a focal infarct scar needs depiction. Which acquisition most directly addresses this tissue question?', 'در اختلال پایدار عملکرد بطن چپ، اسکار کانونی انفارکت باید نشان داده شود. کدام تصویربرداری مستقیماً این پرسش بافتی را پاسخ می‌دهد؟'),
 [L('Cine-bSSFP zur Volumenmessung','Cine bSSFP for volume measurement','Cine-bSSFP برای اندازه‌گیری حجم'),L('T2-Mapping zur Wasserbeurteilung','T2 mapping for water assessment','مپینگ T2 برای ارزیابی آب'),L('First-Pass-Perfusion beim ersten Kontrastdurchgang','First-pass perfusion during initial contrast passage','پرفیوژن عبور اول هنگام نخستین گذر مادهٔ حاجب'),L('LGE nach Gadolinium mit Unterdrückung gesunden Myokards','LGE after gadolinium with suppression of healthy myocardium','LGE پس از گادولینیوم با سرکوب میوکارد سالم')],'D',
 L('LGE stellt fokale Schädigung und Narbe über die unterschiedliche Kontrastverteilung dar. Cine liefert ergänzend Funktion; T2 adressiert Wasser und Perfusion die Durchblutung.', 'LGE depicts focal injury and scar through differences in contrast distribution. Cine adds function, T2 addresses water, and perfusion assesses blood supply.', 'LGE با تفاوت توزیع مادهٔ حاجب آسیب و اسکار کانونی را نشان می‌دهد. Cine عملکرد را تکمیل می‌کند؛ T2 آب و پرفیوژن خون‌رسانی را ارزیابی می‌کنند.'),
 {A:L('Cine zeigt die Funktionsfolge, charakterisiert aber eine fokale Narbe nicht wie LGE.','Cine shows the functional consequence but does not characterise focal scar as LGE does.','Cine پیامد عملکردی را نشان می‌دهد اما اسکار کانونی را مانند LGE توصیف نمی‌کند.'),B:L('T2 beantwortet die Wasser-/Ödemfrage; chronische Narbe muss kein erhöhtes T2 haben.','T2 addresses water/oedema; chronic scar need not have elevated T2.','T2 پرسش آب/ادم را پاسخ می‌دهد؛ اسکار مزمن الزاماً T2 بالا ندارد.'),C:L('First-Pass-Perfusion untersucht die Boluspassage; sie ersetzt keine verzögerte Narbendarstellung.','First-pass perfusion assesses bolus passage and does not replace delayed scar imaging.','پرفیوژن عبور اول گذر بولوس را ارزیابی می‌کند و جای تصویربرداری تأخیری اسکار را نمی‌گیرد.')},CMR,
 L('Welche Gewebefrage ergänzt LGE zur Cine-Funktionsmessung?', 'Which tissue question does LGE add to cine functional assessment?', 'LGE چه پرسش بافتی را به ارزیابی عملکرد با Cine اضافه می‌کند؟'),
 L('Wo und in welcher Verteilung fokale Schädigung/Narbe vorliegt. Das Muster muss mit Klinik und übrigen Sequenzen korreliert werden.', 'Where focal injury/scar lies and how it is distributed. Interpret the pattern with clinical findings and other sequences.', 'محل و توزیع آسیب/اسکار کانونی. الگو باید با بالین و سکانس‌های دیگر تطبیق داده شود.'))

add('kardio-mrt-indikationen','referral',
 L('Bei unklarer LV-Dysfunktion nach Infarkt lautet die Frage, wie viel dysfunktionales Myokard nach Revaskularisation funktionell erholungsfähig sein könnte. Welcher CMR-Kern passt?', 'In unexplained LV dysfunction after infarction, the question is how much dysfunctional myocardium may recover function after revascularisation. Which core CMR protocol fits?', 'در اختلال عملکرد بطن چپ پس از انفارکت، پرسش این است که چه مقدار از میوکارد دچار اختلال ممکن است پس از خون‌رسانی مجدد عملکردش بهبود یابد. هستهٔ مناسب پروتکل CMR چیست؟'),
 [L('Cine und LGE zur Funktion und Narbentransmuralität','Cine and LGE for function and scar transmurality','Cine و LGE برای عملکرد و وسعت تمام‌جداری اسکار'),L('Cine und T2 ohne LGE','Cine and T2 without LGE','Cine و T2 بدون LGE'),L('Ruheperfusion ohne LGE','Rest perfusion without LGE','پرفیوژن استراحت بدون LGE'),L('Cine-Wandbewegung ohne Gewebecharakterisierung','Cine wall motion without tissue characterisation','حرکت دیواره در Cine بدون توصیف بافت')],'A',
 L('Cine erfasst Funktion, LGE die Lage und transmuralen Anteile der Narbe. Geringere Narbentransmuralität ist mit höherer Erholungswahrscheinlichkeit verbunden; eine individuelle Erholung ist damit nicht garantiert.', 'Cine assesses function and LGE scar location and transmural extent. Less transmural scar is associated with a greater probability of recovery, without guaranteeing individual recovery.', 'Cine عملکرد و LGE محل و وسعت تمام‌جداری اسکار را نشان می‌دهند. درگیری تمام‌جداری کمتر با احتمال بالاتر بهبود همراه است، اما بهبود فردی را تضمین نمی‌کند.'),
 {B:L('Cine und T2 erfassen Funktion und Wasser, aber nicht zuverlässig die LGE-Narbentransmuralität.', 'Cine and T2 assess function and water, but not LGE scar transmurality reliably.', 'Cine و T2 عملکرد و آب را ارزیابی می‌کنند، نه وسعت تمام‌جداری اسکار LGE را به‌طور قابل اعتماد.'),C:L('Ruheperfusion allein grenzt Narbe und potenziell erholungsfähige Dysfunktion nicht anhand der Narbentransmuralität ab.', 'Rest perfusion alone does not distinguish scar from potentially recoverable dysfunction using scar transmurality.', 'پرفیوژن استراحت به‌تنهایی با معیار وسعت تمام‌جداری اسکار، اسکار را از اختلال بالقوه قابل بهبود جدا نمی‌کند.'),D:L('Gleiche Wandbewegungsstörung kann unterschiedliche Narbenanteile haben; Cine allein liefert diese Gewebeinformation nicht.', 'Similar wall-motion abnormalities can have different scar extents; cine alone does not provide that tissue information.', 'اختلال حرکتی مشابه می‌تواند وسعت اسکار متفاوتی داشته باشد؛ Cine به‌تنهایی این اطلاعات بافتی را نمی‌دهد.')},VIABILITY,
 L('Wie formuliert man eine CMR-Anmeldung bei postischämischer LV-Dysfunktion gezielt?', 'How can a CMR referral for post-ischaemic LV dysfunction be focused?', 'درخواست هدفمند CMR در اختلال عملکرد بطن چپ پس از ایسکمی چگونه نوشته می‌شود؟'),
 L('Bekannte Ischämie/Revaskularisation und Funktionsbefund nennen; nach LV-Funktion, Narbenverteilung und Transmuralität zur Abschätzung der Erholungswahrscheinlichkeit fragen.', 'State the ischaemic/revascularisation history and functional findings; ask for LV function, scar distribution and transmural extent to estimate recovery probability.', 'سابقهٔ ایسکمی/خون‌رسانی مجدد و یافتهٔ عملکردی را ذکر کنید و عملکرد بطن چپ، توزیع اسکار و وسعت تمام‌جداری را برای برآورد احتمال بهبود بخواهید.'))

add('kardio-mrt-indikationen','iron',
 L('Bei transfusionsbedingter Eisenüberladung soll die myokardiale Eisenbelastung im Verlauf beurteilt werden. Welcher Baustein gehört gezielt ins CMR-Protokoll?', 'In transfusional iron overload, myocardial iron burden needs serial assessment. Which component specifically belongs in the CMR protocol?', 'در اضافه‌بار آهن ناشی از انتقال خون، بار آهن میوکارد باید در پیگیری ارزیابی شود. کدام بخش به‌طور هدفمند در پروتکل CMR قرار می‌گیرد؟'),
 [L('Stressperfusion als alleinige Gewebemessung','Stress perfusion as the sole tissue measurement','پرفیوژن استرس به‌عنوان تنها اندازه‌گیری بافتی'),L('Ausschließlich Koronarangiographie','Coronary angiography alone','فقط آنژیوگرافی کرونر'),L('T2*-Mapping mit standardisierter Verlaufstechnik','T2* mapping with standardised serial technique','مپینگ T2* با روش استاندارد در پیگیری'),L('LGE allein ohne weitere Gewebeparameter','LGE alone without other tissue parameters','فقط LGE بدون پارامتر بافتی دیگر')],'C',
 L('T2* ist der für die Eisenfrage vorgesehene Gewebeparameter. Für Vergleiche sind konsistente Akquisition und Auswertung wichtig; Funktion und andere klinische Fragen können zusätzliche Sequenzen erfordern.', 'T2* is the tissue parameter targeted to the iron question. Serial comparisons require consistent acquisition and analysis; function and other clinical questions can require additional sequences.', 'T2* پارامتر بافتی هدفمند برای پرسش آهن است. مقایسهٔ پیگیری به تصویربرداری و تحلیل یکنواخت نیاز دارد؛ عملکرد و پرسش‌های بالینی دیگر ممکن است سکانس‌های بیشتری بخواهند.'),
 {A:L('Perfusion untersucht Durchblutung und ersetzt keine Eisenmessung.', 'Perfusion assesses blood supply and does not replace iron measurement.', 'پرفیوژن خون‌رسانی را ارزیابی می‌کند و جای اندازه‌گیری آهن را نمی‌گیرد.'),B:L('Koronaranatomie quantifiziert die myokardiale Eisenbelastung nicht.', 'Coronary anatomy does not quantify myocardial iron burden.', 'آناتومی کرونر بار آهن میوکارد را کمی‌سازی نمی‌کند.'),D:L('LGE kann Schädigung ergänzend darstellen, ersetzt die T2*-Quantifizierung aber nicht.', 'LGE may add information about injury but does not replace T2* quantification.', 'LGE می‌تواند اطلاعات مکمل آسیب بدهد اما جای کمی‌سازی T2* را نمی‌گیرد.')},CMR,
 L('Benötigt die CMR-Eisenmessung mit T2* Gadolinium?', 'Does CMR iron assessment using T2* require gadolinium?', 'آیا ارزیابی آهن با T2* در CMR به گادولینیوم نیاز دارد؟'),
 L('Die T2*-Messung selbst erfolgt nativ. Ob weitere Kontrastsequenzen sinnvoll sind, richtet sich nach den zusätzlichen klinischen Fragen.', 'T2* measurement itself is non-contrast. Whether additional contrast sequences are useful depends on the other clinical questions.', 'خود اندازه‌گیری T2* بدون مادهٔ حاجب انجام می‌شود. سودمندی سکانس‌های حاجب دیگر به پرسش‌های بالینی همراه بستگی دارد.'))

add('kardio-mrt-indikationen','urgent-care',
 L('Ein Patient hat anhaltende ischämietypische Schmerzen, ST-Hebungen und Kreislaufinstabilität. Welche Rolle hat CMR jetzt?', 'A patient has ongoing ischaemic-type chest pain, ST elevation and haemodynamic instability. What is the role of CMR now?', 'بیمار درد مداوم تیپیک ایسکمیک، بالا رفتن ST و ناپایداری همودینامیک دارد. نقش CMR در این لحظه چیست؟'),
 [L('Vor jeder Reperfusion zunächst vollständige Stress-CMR','Complete stress CMR before any reperfusion','CMR کامل استرس پیش از هر بازخون‌رسانی'),L('CMR statt klinischem Akutpfad, da ohne Röntgenstrahlung','CMR instead of the acute pathway because it uses no X-rays','CMR به‌جای مسیر اورژانسی چون اشعهٔ ایکس ندارد'),L('Eine native Cine-Serie genügt zum Ausschluss eines akuten Koronarverschlusses','Native cine alone excludes acute coronary occlusion','Cine بدون حاجب به‌تنهایی انسداد حاد کرونر را رد می‌کند'),L('Dringliche Akutversorgung nicht für CMR verzögern; spätere CMR nach Stabilisierung gezielt planen','Do not delay urgent care for CMR; plan targeted CMR after stabilisation','درمان فوری را برای CMR به تأخیر نیندازید؛ CMR هدفمند را پس از پایدارسازی برنامه‌ریزی کنید')],'D',
 L('CMR kann nach Stabilisierung Schädigung und Funktion charakterisieren. Sie darf in dieser instabilen Akutsituation den dringlichen Koronar-/Reperfusionspfad nicht verzögern.', 'CMR can characterise injury and function after stabilisation. In this unstable acute presentation it must not delay the urgent coronary/reperfusion pathway.', 'CMR پس از پایدارسازی می‌تواند آسیب و عملکرد را مشخص کند. در این وضعیت حاد ناپایدار نباید مسیر فوری بررسی کرونر/بازخون‌رسانی را عقب بیندازد.'),
 {A:L('Stress-CMR ist kein vorgeschalteter Pflichtschritt bei diesem instabilen Akutbild.', 'Stress CMR is not a prerequisite in this unstable acute presentation.', 'CMR استرس در این تظاهر حاد ناپایدار پیش‌شرط نیست.'),B:L('Fehlende ionisierende Strahlung hebt die zeitkritische klinische Indikation nicht auf.', 'Absence of ionising radiation does not override the time-critical clinical indication.', 'نداشتن پرتو یونیزان ضرورت بالینی وابسته به زمان را از بین نمی‌برد.'),C:L('Cine beurteilt Funktion, schließt einen akuten Koronarverschluss aber nicht zuverlässig aus.', 'Cine assesses function but cannot reliably exclude acute coronary occlusion.', 'Cine عملکرد را ارزیابی می‌کند اما انسداد حاد کرونر را با اطمینان رد نمی‌کند.')},'https://academic.oup.com/eurheartj/article/44/38/3720/7243210',
 L('Welche Grenze hat die Aussage „CMR ohne ionisierende Strahlung“ im Akutfall?', 'What limitation does “CMR without ionising radiation” have in an emergency?', 'عبارت «CMR بدون پرتو یونیزان» در اورژانس چه محدودیتی دارد؟'),
 L('Die Wahl muss zur klinischen Dringlichkeit und Stabilität passen; Strahlungsfreiheit rechtfertigt keine Verzögerung einer notwendigen Akuttherapie.', 'The choice must fit clinical urgency and stability; lack of radiation does not justify delaying necessary emergency treatment.', 'انتخاب باید با فوریت بالینی و پایداری بیمار سازگار باشد؛ نبود پرتو تأخیر در درمان ضروری اورژانسی را توجیه نمی‌کند.'))

add('myokardinfarkt-mrt','scar-probability',
 L('Zwei dysfunktionale LV-Segmente haben vergleichbare Wandbewegungsstörungen. Segment 1 zeigt 20 %, Segment 2 etwa 90 % transmuralen LGE-Anteil. Welche Aussage zur Erholung nach Revaskularisation ist angemessen?', 'Two dysfunctional LV segments have comparable wall-motion abnormalities. Segment 1 has 20% and segment 2 about 90% transmural LGE. Which statement about recovery after revascularisation is appropriate?', 'دو سگمان بطن چپ اختلال حرکتی مشابه دارند. وسعت تمام‌جداری LGE در سگمان ۱ برابر ۲۰٪ و در سگمان ۲ حدود ۹۰٪ است. کدام گزاره دربارهٔ بهبود پس از خون‌رسانی مجدد مناسب است؟'),
 [L('Segment 2 hat wegen stärkerem Enhancement die höhere Erholungschance','Segment 2 has the greater recovery probability because enhancement is greater','سگمان ۲ به دلیل افزایش کنتراست بیشتر احتمال بهبود بالاتری دارد'),L('Die Erholungswahrscheinlichkeit ist in Segment 1 höher; eine Garantie ergibt sich daraus nicht','Recovery is more likely in segment 1, without a guarantee','احتمال بهبود در سگمان ۱ بیشتر است، بدون تضمین'),L('Gleiche Wandbewegung bedeutet gleiche Erholungschance unabhängig vom LGE','Equal wall motion implies equal recovery probability regardless of LGE','حرکت یکسان دیواره به معنای احتمال بهبود برابر مستقل از LGE است'),L('Segment 1 ist wegen subendokardialem LGE vollständig funktionsunfähig','Segment 1 cannot recover any function because it has subendocardial LGE','سگمان ۱ به دلیل LGE زیراندوکاردی هیچ عملکردی را بازنمی‌یابد')],'B',
 L('Die transmuralen Narbenanteile ergänzen die Funktionsmessung: mit mehr LGE nimmt die Wahrscheinlichkeit kontraktiler Erholung ab. Die Untersuchung erlaubt eine probabilistische, keine binäre Prognose.', 'Transmural scar extent adds to functional imaging: greater LGE is associated with lower probability of contractile recovery. This supports a probabilistic rather than binary prediction.', 'وسعت تمام‌جداری اسکار مکمل ارزیابی عملکرد است: LGE بیشتر با احتمال کمتر بهبود انقباضی همراه است. این ارزیابی احتمالی است، نه پیش‌بینی دوحالتی.'),
 {A:L('Mehr LGE bedeutet mehr geschädigtes Gewebe, nicht bessere Perfusion oder garantierte Erholung.', 'More LGE represents more injured tissue, not better perfusion or guaranteed recovery.', 'LGE بیشتر نشان‌دهندهٔ بافت آسیب‌دیدهٔ بیشتر است، نه پرفیوژن بهتر یا بهبود تضمین‌شده.'),C:L('Ähnliche Wandbewegung kann bei unterschiedlichem Narbenanteil auftreten.', 'Similar wall motion can occur with different amounts of scar.', 'حرکت مشابه دیواره می‌تواند با مقدار اسکار متفاوت رخ دهد.'),D:L('Nichttransmurale Schädigung lässt einen nicht kontrastierenden äußeren Myokardanteil übrig; vollständiger Funktionsverlust ist daraus nicht abzuleiten.', 'Nontransmural injury leaves an outer myocardial component without enhancement; complete inability to recover cannot be inferred.', 'آسیب غیرتمام‌جداری بخشی از میوکارد خارجی را بدون افزایش کنتراست باقی می‌گذارد؛ ناتوانی کامل از بهبود از آن نتیجه نمی‌شود.')},VIABILITY,
 L('Warum ist „LGE vorhanden = gesamtes Segment nicht vital“ zu grob?', 'Why is “LGE present = the entire segment is nonviable” too crude?', 'چرا «وجود LGE یعنی کل سگمان غیرزنده است» بیش از حد ساده است؟'),
 L('LGE kann nur einen Teil der Wand betreffen. Die Transmuralität und übrige Funktions-/Klinikinformation bestimmen die Abschätzung der Erholungswahrscheinlichkeit.', 'LGE may affect only part of the wall. Transmural extent and the remaining functional and clinical information inform the estimated recovery probability.', 'LGE ممکن است فقط بخشی از دیواره را درگیر کند. وسعت تمام‌جداری همراه با اطلاعات عملکردی و بالینی برای برآورد احتمال بهبود به‌کار می‌رود.'))

add('myokardinfarkt-mrt','mvo-core',
 L('Nach reperfundiertem akutem Infarkt liegt ein hypoenhancender Kern innerhalb eines stark kontrastierenden Infarktareals. Welche Einordnung passt am besten?', 'After reperfused acute infarction, a hypoenhanced core lies within a hyperenhanced infarct region. Which interpretation fits best?', 'پس از انفارکت حاد بازخون‌رسانی‌شده، هسته‌ای با افزایش کنتراست کمتر درون ناحیهٔ انفارکت با افزایش کنتراست زیاد قرار دارد. کدام تفسیر مناسب‌تر است؟'),
 [L('Erhaltenes gesundes Myokard mit sicher guter Erholung','Preserved healthy myocardium with assured good recovery','میوکارد سالم حفظ‌شده با بهبود حتماً خوب'),L('Intrakavitäre Thrombusmasse allein aufgrund dunklen Signals','Intracavitary thrombus based on dark signal alone','تودهٔ ترومبوس داخل حفره صرفاً به دلیل سیگنال تیره'),L('Mikrovaskuläre Obstruktion im Infarktkern','Microvascular obstruction in the infarct core','انسداد میکروواسکولار در هستهٔ انفارکت'),L('Nichtischämische epikardiale Narbe','Non-ischaemic epicardial scar','اسکار غیرایسکمیک اپیکاردی')],'C',
 L('Die Lokalisation eines dunklen Kerns im kontrastierenden Infarktgebiet passt zu MVO. Fehlende Kontrastierung ist in diesem Kontext kein Vitalitätszeichen; Lage und übrige Sequenzen müssen mitbeurteilt werden.', 'A dark core within the enhanced infarct region fits MVO. Lack of enhancement in this context is not a sign of viability; location and other sequences must also be assessed.', 'هستهٔ تیره در ناحیهٔ انفارکت با افزایش کنتراست با MVO سازگار است. نبود افزایش کنتراست در این زمینه نشانهٔ حیات نیست؛ محل و سکانس‌های دیگر نیز باید بررسی شوند.'),
 {A:L('Dunkles Signal bedeutet nicht in jeder Kontrastsituation gesundes Gewebe; der Infarktkern ist hier entscheidend.', 'Dark signal does not mean healthy tissue in every contrast context; the infarct-core location matters here.', 'سیگنال تیره در هر زمینهٔ کنتراستی به معنای بافت سالم نیست؛ قرارگیری در هستهٔ انفارکت مهم است.'),B:L('Ein Thrombus ist kavitäts-/wandständig zu lokalisieren; beschrieben ist ein intramyokardialer Kern.', 'A thrombus must be located in the cavity or along its wall; the described core is intramyocardial.', 'ترومبوس باید داخل حفره یا کنار دیوارهٔ آن قرار گیرد؛ هستهٔ توصیف‌شده داخل میوکارد است.'),D:L('Ein epikardiales Narbenmuster entspricht nicht dem beschriebenen dunklen Infarktkern.', 'An epicardial scar pattern does not match the described dark infarct core.', 'الگوی اسکار اپیکاردی با هستهٔ تیرهٔ انفارکت توصیف‌شده مطابقت ندارد.')},'https://pubmed.ncbi.nlm.nih.gov/9498540/',
 L('Welche Ortsinformation trennt MVO und wandständigen Thrombus?', 'Which location information helps distinguish MVO from mural thrombus?', 'کدام اطلاعات مکانی به افتراق MVO از ترومبوس جداری کمک می‌کند؟'),
 L('MVO liegt im myokardialen Infarktgebiet; ein wandständiger Thrombus liegt an der kavitätsseitigen Wand. Dunkles Signal allein reicht nicht.', 'MVO lies within infarcted myocardium; mural thrombus lies along the cavity-facing wall. Dark signal alone is insufficient.', 'MVO در میوکارد انفارکته قرار دارد؛ ترومبوس جداری در سمت حفره‌ای دیواره است. سیگنال تیره به‌تنهایی کافی نیست.'))

add('myokardinfarkt-mrt','acute-protocol',
 L('Nach erfolgreicher Behandlung des Infarktgefäßes ist der Patient stabil. CMR soll LV-Funktion, Infarktausmaß und mikrovaskuläre Schädigung erfassen. Welche Kombination ist ein passender Kern?', 'After successful treatment of the culprit vessel, the patient is stable. CMR should assess LV function, infarct extent and microvascular injury. Which combination is an appropriate core?', 'پس از درمان موفق رگ مسئول انفارکت، بیمار پایدار است. CMR باید عملکرد بطن چپ، وسعت انفارکت و آسیب میکروواسکولار را ارزیابی کند. کدام ترکیب هستهٔ مناسبی است؟'),
 [L('Cine und LGE; Gewebecharakterisierung bzw. frühe Kontrastsequenzen je nach Fragestellung ergänzen','Cine and LGE; add tissue characterisation or early contrast imaging according to the question','Cine و LGE؛ افزودن توصیف بافت یا تصویربرداری زودرس پس از حاجب بر اساس پرسش'),L('Cine-Funktionsmessung ohne Kontrastsequenzen','Cine functional assessment without contrast sequences','ارزیابی عملکرد با Cine بدون سکانس‌های حاجب'),L('LGE ohne Cine-Funktionsmessung','LGE without cine functional assessment','LGE بدون ارزیابی عملکرد با Cine'),L('Ruheperfusion ohne Cine und LGE','Rest perfusion without cine and LGE','پرفیوژن استراحت بدون Cine و LGE')],'A',
 L('Cine erfasst die Ventrikelfunktion, LGE die myokardiale Schädigung und kann späte MVO zeigen. Weitere Sequenzen werden gezielt ergänzt; Stress ist nach Infarkt kein universeller Pflichtbestandteil.', 'Cine assesses ventricular function, while LGE depicts myocardial injury and may show late MVO. Add other sequences to address specific questions; stress imaging is not universally required after infarction.', 'Cine عملکرد بطنی را ارزیابی می‌کند و LGE آسیب میوکارد و گاهی MVO دیررس را نشان می‌دهد. سکانس‌های دیگر هدفمند اضافه می‌شوند؛ تصویربرداری استرس پس از انفارکت الزام همگانی نیست.'),
 {B:L('Cine allein zeigt die Funktionsstörung, aber nicht die vollständige kontrastbasierte Infarkt-/MVO-Charakterisierung.', 'Cine alone shows dysfunction but not complete contrast-based infarct/MVO characterisation.', 'Cine به‌تنهایی اختلال عملکرد را نشان می‌دهد، نه توصیف کامل انفارکت/MVO مبتنی بر حاجب را.'),C:L('LGE trägt zur Infarkt-/MVO-Beurteilung bei, ersetzt aber keine zeitaufgelöste Ventrikelfunktionsmessung.', 'LGE contributes to infarct/MVO assessment but does not replace time-resolved ventricular functional measurement.', 'LGE در ارزیابی انفارکت/MVO کمک می‌کند اما جای اندازه‌گیری زمان‌تفکیک‌شدهٔ عملکرد بطنی را نمی‌گیرد.'),D:L('Ruheperfusion ist eine mögliche Ergänzung, liefert aber allein weder vollständige LV-Funktion noch verzögerte Infarktdarstellung.', 'Rest perfusion is a possible adjunct but alone provides neither complete LV function nor delayed infarct imaging.', 'پرفیوژن استراحت مکمل احتمالی است، اما به‌تنهایی نه عملکرد کامل بطن چپ را می‌دهد و نه تصویر تأخیری انفارکت را.')},CMR,
 L('Ist Stressperfusion obligatorisch in jeder CMR nach akutem Infarkt?', 'Is stress perfusion mandatory in every CMR after acute infarction?', 'آیا پرفیوژن استرس در همهٔ CMRهای پس از انفارکت حاد الزامی است؟'),
 L('Nein. Protokoll an Stabilität und Frage anpassen; nach behandeltem Infarktgefäß kann Stress bei gezielter Frage nach Ischämie anderer Territorien erwogen werden.', 'No. Tailor the protocol to stability and the question; after culprit-vessel treatment, stress may be considered for suspected ischaemia in other territories.', 'خیر. پروتکل با پایداری و پرسش تنظیم می‌شود؛ پس از درمان رگ مسئول، برای بررسی هدفمند ایسکمی قلمروهای دیگر می‌توان استرس را در نظر گرفت.'))

add('aortenbogen','branch-report',
 L('Vor einem supraaortalen Kathetereingriff zeigt die CTA einen gemeinsamen Ursprung von Truncus brachiocephalicus und linker A. carotis communis. Welche Beschreibung ist für die Planung am hilfreichsten?', 'Before a supra-aortic catheter procedure, CTA shows a common origin of the brachiocephalic trunk and left common carotid artery. Which description best supports planning?', 'پیش از مداخلهٔ کاتتری سوپرا‌آئورتیک، CTA منشأ مشترک تنهٔ براکیوسفالیک و کاروتید مشترک چپ را نشان می‌دهد. کدام توصیف برای برنامه‌ریزی مفیدتر است؟'),
 [L('„Boviner Bogen“, ohne weitere Beschreibung','“Bovine arch”, without further description','«قوس گاوی»، بدون توضیح بیشتر'),L('Rechter Aortenbogen aufgrund zweier Abgänge','Right aortic arch because there are two origins','قوس راست به دلیل وجود دو منشأ'),L('Doppelter Aortenbogen aufgrund gemeinsamen Ostiums','Double aortic arch because of a common ostium','قوس دوتایی به دلیل دهانهٔ مشترک'),L('Gemeinsamen Ursprung, anschließende Aufteilung und übrige Abgänge konkret beschreiben','Describe the shared origin, subsequent division and remaining branches explicitly','توصیف مشخص منشأ مشترک، تقسیم بعدی و شاخه‌های دیگر')],'D',
 L('Konkrete Ursprungs- und Verlaufsangaben sind interventionell nutzbar. Ein gemeinsamer Abgang ist eine Verzweigungsvariante und allein weder ein rechter noch ein doppelter Bogen.', 'Explicit origin and course are useful for intervention. A shared origin is a branching variant and alone establishes neither a right nor a double arch.', 'ذکر دقیق منشأ و مسیر برای مداخله مفید است. منشأ مشترک یک واریانت شاخه‌بندی است و به‌تنهایی نه قوس راست را ثابت می‌کند و نه قوس دوتایی را.'),
 {A:L('Der umgangssprachliche Sammelbegriff kann unterschiedliche Verzweigungsmuster verdecken.', 'The colloquial umbrella term can obscure different branching patterns.', 'اصطلاح عامیانه ممکن است الگوهای متفاوت شاخه‌بندی را پنهان کند.'),B:L('Die Bogenseite wird durch den Verlauf relativ zur Trachea bestimmt, nicht allein durch die Zahl der Abgänge.', 'Arch side depends on its course relative to the trachea, not solely the number of origins.', 'سمت قوس از مسیر نسبت به تراشه تعیین می‌شود، نه صرفاً تعداد منشأها.'),C:L('Ein gemeinsames Ostium bedeutet keine zwei die Trachea umgebenden Bogenanteile.', 'A shared ostium does not imply two arch components surrounding the trachea.', 'دهانهٔ مشترک به معنای دو بخش قوس در اطراف تراشه نیست.')},'https://pubmed.ncbi.nlm.nih.gov/23694814/',
 L('Was sollte ein interventionell nutzbarer Aortenbogenbefund zu den Abgängen enthalten?', 'What branch information makes an aortic arch report useful for intervention?', 'چه اطلاعات شاخه‌ای گزارش قوس آئورت را برای مداخله مفید می‌کند؟'),
 L('Ursprung, Reihenfolge und Verlauf der supra­aortalen Gefäße konkret benennen; einen Sammelbegriff nicht als einzige Beschreibung verwenden.', 'Explicitly name the origin, order and course of the supra-aortic vessels; do not use an umbrella term as the only description.', 'منشأ، ترتیب و مسیر عروق سوپرا‌آئورتیک را مشخص ذکر کنید؛ اصطلاح کلی تنها توصیف نباشد.'))

add('aortenbogen','ring-symptoms',
 L('Ein Kind hat Stridor und Schluckbeschwerden. Die Schnittbildgebung zeigt einen doppelten Aortenbogen um Trachea und Ösophagus. Welche Zusatzangabe verknüpft den Gefäßbefund am direktesten mit diesen Symptomen?', 'A child has stridor and dysphagia. Cross-sectional imaging shows a double aortic arch around the trachea and oesophagus. Which additional finding most directly connects the vascular anatomy to these symptoms?', 'کودک استریدور و اختلال بلع دارد. تصویربرداری مقطعی قوس دوتایی دور تراشه و مری را نشان می‌دهد. کدام یافتهٔ تکمیلی ارتباط آناتومی عروقی با این علائم را مستقیم‌تر نشان می‌دهد؟'),
 [L('Die Reihenfolge der supraaortalen Abgänge','The order of the supra-aortic branches','ترتیب شاخه‌های سوپرا‌آئورتیک'),L('Ringanatomie und Ausmaß der Tracheal-/Ösophaguskompression','Ring anatomy and degree of tracheal/oesophageal compression','آناتومی حلقه و میزان فشار بر تراشه/مری'),L('Den Durchmesser der Aorta ascendens','The diameter of the ascending aorta','قطر آئورت صعودی'),L('Welcher der beiden Bogenanteile dominant ist','Which of the two arch components is dominant','اینکه کدام بخش قوس غالب است')],'B',
 L('Ein Gefäßring kann die Atem- und Speisewege komprimieren. Die Beziehung der Bogenanteile zu Trachea und Ösophagus sowie die Engstelle gehören zur symptomorientierten Beurteilung.', 'A vascular ring can compress the airway and oesophagus. The arch components’ relationship to these structures and the site of narrowing belong in symptom-directed assessment.', 'حلقهٔ عروقی می‌تواند راه هوایی و مری را تحت فشار قرار دهد. ارتباط بخش‌های قوس با این ساختارها و محل تنگی بخشی از ارزیابی متناسب با علائم است.'),
 {A:L('Die Abgangsreihenfolge gehört zur Planung, belegt aber nicht die symptomrelevante Kompression.', 'Branch order supports planning but does not demonstrate symptom-relevant compression.', 'ترتیب شاخه‌ها برای برنامه‌ریزی مفید است اما فشار مرتبط با علائم را نشان نمی‌دهد.'),C:L('Ein einzelner Durchmesser erfasst Ringbildung und Kompression nicht.', 'A single diameter does not characterise the ring and compression.', 'یک قطر منفرد حلقه و فشار را توصیف نمی‌کند.'),D:L('Die Dominanz ist für die Operationsplanung wichtig, beschreibt allein aber nicht den Kompressionseffekt.', 'Arch dominance matters for surgical planning but alone does not describe the compressive effect.', 'غالب بودن قوس برای برنامه‌ریزی جراحی مهم است اما به‌تنهایی اثر فشاری را نشان نمی‌دهد.')},RINGS,
 L('Welche Symptome machen eine komprimierende Aortenbogenanomalie klinisch relevant?', 'Which symptoms raise concern for a compressive aortic arch anomaly?', 'کدام علائم احتمال ناهنجاری فشاری قوس آئورت را مطرح می‌کنند؟'),
 L('Etwa Stridor, wiederkehrende Atemwegsbeschwerden und Dysphagie; Anatomie und tatsächliche Kompression müssen bildgebend korreliert werden.', 'For example stridor, recurrent respiratory symptoms and dysphagia; correlate imaging anatomy with actual compression.', 'مثلاً استریدور، علائم تنفسی تکرارشونده و اختلال بلع؛ آناتومی تصویری باید با فشار واقعی تطبیق داده شود.'))

add('aortenbogen','aberrant-branch',
 L('Die CTA zeigt an einem linken Aortenbogen vier getrennte Abgänge: rechte Karotis, linke Karotis, linke Subclavia und zuletzt die rechte Subclavia mit retroösophagealem Verlauf. Welche Variante ist beschrieben?', 'CTA shows four separate branches from a left aortic arch: right carotid, left carotid, left subclavian, then the right subclavian passing behind the oesophagus. Which variant is described?', 'CTA چهار شاخهٔ مجزا از قوس چپ نشان می‌دهد: کاروتید راست، کاروتید چپ، ساب‌کلاوین چپ و در آخر ساب‌کلاوین راست با مسیر پشت مری. کدام واریانت توصیف شده است؟'),
 [L('Gemeinsamer Ursprung von Truncus brachiocephalicus und linker Karotis','Common origin of brachiocephalic trunk and left carotid','منشأ مشترک تنهٔ براکیوسفالیک و کاروتید چپ'),L('Direkter Abgang der linken Vertebralarterie','Direct origin of the left vertebral artery','منشأ مستقیم شریان مهره‌ای چپ'),L('Aberrante rechte A. subclavia','Aberrant right subclavian artery','شریان ساب‌کلاوین راست نابجا'),L('Spiegelbildliches Abgangsmuster eines rechten Bogens','Mirror-image branching of a right arch','شاخه‌بندی آینه‌ای قوس راست')],'C',
 L('Die rechte Subclavia entspringt hier als letzter Ast direkt aus dem linken Bogen und verläuft hinter dem Ösophagus. Diese Ursprungs-/Verlaufskombination beschreibt eine aberrante rechte Subclavia; Kompression muss zusätzlich geprüft werden.', 'Here the right subclavian arises directly as the last branch of the left arch and passes behind the oesophagus. This origin/course combination describes an aberrant right subclavian; compression requires separate assessment.', 'در اینجا ساب‌کلاوین راست مستقیماً آخرین شاخهٔ قوس چپ است و از پشت مری می‌گذرد. این ترکیب منشأ و مسیر، ساب‌کلاوین راست نابجا را توصیف می‌کند؛ فشار باید جداگانه بررسی شود.'),
 {A:L('Es sind vier getrennte Ursprünge beschrieben, kein gemeinsames Ostium.', 'Four separate origins are described, rather than a shared ostium.', 'چهار منشأ مجزا توصیف شده‌اند، نه یک دهانهٔ مشترک.'),B:L('Der zusätzlich ungewöhnlich entspringende Ast ist hier die rechte Subclavia, nicht die linke Vertebralarterie.', 'The abnormally arising branch here is the right subclavian, not the left vertebral artery.', 'شاخهٔ دارای منشأ غیرمعمول در اینجا ساب‌کلاوین راست است، نه شریان مهره‌ای چپ.'),D:L('Der Bogen ist ausdrücklich linksseitig; Ursprung und retroösophagealer Verlauf passen nicht zur genannten Spiegelbildvariante.', 'The arch is explicitly left-sided; the origin and retro-oesophageal course do not match the proposed mirror-image variant.', 'قوس صریحاً چپ است؛ منشأ و مسیر پشت مری با واریانت آینه‌ای پیشنهادی سازگار نیست.')},'https://pubmed.ncbi.nlm.nih.gov/23740497/',
 L('Welche Angaben gehören bei einer aberranten Subclavia in den Befund?', 'What should a report of an aberrant subclavian artery include?', 'در گزارش ساب‌کلاوین نابجا چه اطلاعاتی لازم است؟'),
 L('Seite, Ursprung und Verlauf, Beziehung zu Trachea/Ösophagus sowie relevante Kompression oder Dilatation; nicht allein das Variantenlabel.', 'Side, origin and course, relationship to trachea/oesophagus, and relevant compression or dilatation; not just the variant label.', 'سمت، منشأ و مسیر، ارتباط با تراشه/مری و فشار یا اتساع مهم؛ نه فقط نام واریانت.'))

const definitions=[
 ['lung-rads','/thorax/lung-rads',L('Lung-RADS v2022','Lung-RADS v2022','Lung-RADS نسخهٔ ۲۰۲۲')],
 ['kardio-mrt-basics','/thorax/kardio/kardio-mrt-basics',L('Kardio-MRT: Grundlagen','Cardiac MRI: basics','MRI قلب: مبانی')],
 ['kardio-mrt-indikationen','/thorax/kardio/kardio-mrt-indikationen',L('Kardio-MRT: Indikationen','Cardiac MRI: indications','MRI قلب: اندیکاسیون‌ها')],
 ['myokardinfarkt-mrt','/thorax/kardio/myokardinfarkt-mrt',L('Myokardinfarkt im MRT','Myocardial infarction on MRI','انفارکت میوکارد در MRI')],
 ['aortenbogen','/thorax/anatomie/aortenbogen',L('Aortenbogen','Aortic arch','قوس آئورت')],
]
const p=(v,lang)=>v[lang]??v.de
export function newQuestions(lang='de'){return records.map(r=>({id:`aq-thorax-${r.topic}-${lang}-${r.key}`,fach:'thorax',tags:[r.topic],question:p(r.question,lang),options:r.options.map((v,i)=>({id:'ABCD'[i],text:p(v,lang)})),correct:r.correct,explanation:p(r.explanation,lang),wrongExplanations:Object.fromEntries(Object.entries(r.feedback).map(([id,v])=>[id,p(v,lang)])),source:r.source}))}
export const newCards=records.map(r=>({id:`aq-thorax-${r.topic}-${r.key}`,topicId:r.topic,category:L('Klinische Anwendung','Clinical application','کاربرد بالینی'),front:r.front,answer:r.answer,explanation:r.explanation,source:r.source}))
export const topics=definitions.map(([id,route,title])=>({id,title,subject:'thorax',description:L('Klinisch orientierte Fragen und Wiederholung.','Clinical questions and retrieval practice.','پرسش‌های بالینی و مرور فعال.'),href:`/flashcards/${id}`}))
const goalText={
 'lung-rads':[
  L('Einen soliden Baseline-Nodulus kategorisieren und das Intervall begründen.','Categorise a baseline solid nodule and justify follow-up.','دسته‌بندی ندول جامد اولیه و توجیه فاصلهٔ پیگیری.'),
  L('Bei einem neuen Nodulus die passenden statt der Baseline-Schwellen anwenden.','Apply new-nodule rather than baseline thresholds.','اعمال آستانه‌های ندول جدید به‌جای آستانه‌های اولیه.'),
  L('Nach früher Stabilität das gestufte Management anwenden.','Apply stepped management after early stability.','اعمال مدیریت مرحله‌ای پس از ثبات زودرس.')],
 'kardio-mrt-basics':[
  L('Den Datensatz für eine vollständige LV-Volumen-/EF-Messung wählen.','Select data for complete LV volume and EF measurement.','انتخاب دادهٔ لازم برای اندازه‌گیری کامل حجم و EF بطن چپ.'),
  L('Funktions-, Perfusions-, Ödem- und Narbenfragen den CMR-Bausteinen zuordnen.','Match functional, perfusion, oedema and scar questions to CMR components.','تطبیق پرسش عملکرد، پرفیوژن، ادم و اسکار با بخش‌های CMR.'),
  L('Den Narbenbaustein LGE gegenüber Funktions-, Perfusions- und Ödembildgebung auswählen.','Select scar imaging with LGE rather than functional, perfusion or oedema imaging.','انتخاب تصویربرداری اسکار با LGE در برابر تصویربرداری عملکرد، پرفیوژن یا ادم.')],
 'kardio-mrt-indikationen':[
  L('Eine Vitalitätsfrage in einen gezielten CMR-Auftrag übersetzen.','Translate a viability question into a focused CMR referral.','تبدیل پرسش حیات میوکارد به درخواست هدفمند CMR.'),
  L('Für Eisenüberladung den passenden nativen Gewebeparameter wählen.','Select the appropriate non-contrast tissue parameter for iron overload.','انتخاب پارامتر بافتی مناسب بدون حاجب برای اضافه‌بار آهن.'),
  L('Die CMR-Indikation gegen zeitkritische Akutversorgung abgrenzen.','Distinguish a CMR indication from time-critical acute care.','تفکیک اندیکاسیون CMR از درمان حاد وابسته به زمان.')],
 'myokardinfarkt-mrt':[
  L('Narbentransmuralität probabilistisch für Funktionserholung interpretieren.','Interpret scar transmurality probabilistically for functional recovery.','تفسیر احتمالی وسعت تمام‌جداری اسکار برای بهبود عملکرد.'),
  L('Einen dunklen Kern im Infarktgebiet kontextgerecht als MVO einordnen.','Interpret a dark infarct core as MVO in context.','تفسیر هستهٔ تیرهٔ انفارکت به‌عنوان MVO در زمینهٔ مناسب.'),
  L('Nach stabilisiertem Infarkt einen frageorientierten CMR-Kern wählen.','Choose a question-led CMR core after stabilised infarction.','انتخاب هستهٔ هدفمند CMR پس از پایدارسازی انفارکت.')],
 'aortenbogen':[
  L('Einen gemeinsamen Abgang präzise für die Eingriffsplanung beschreiben.','Describe a shared origin precisely for procedure planning.','توصیف دقیق منشأ مشترک برای برنامه‌ریزی مداخله.'),
  L('Bei Ringsymptomen die symptomrelevante Kompression gezielt beurteilen.','Assess symptom-relevant compression in a vascular ring.','ارزیابی هدفمند فشار مرتبط با علائم در حلقهٔ عروقی.'),
  L('Eine aberrante Subclavia aus Ursprung und Verlauf erkennen.','Identify an aberrant subclavian from its origin and course.','شناسایی ساب‌کلاوین نابجا از منشأ و مسیر.')],
}
export const routeCoverage=definitions.map(([topicId,route,title])=>({route,topicId,title,status:'authored_pending_independent_review',learningGoals:records.filter(r=>r.topic===topicId).map((r,i)=>({id:r.key,text:goalText[topicId][i],questionIds:[`aq-thorax-${r.topic}-de-${r.key}`],cardIds:[`aq-thorax-${r.topic}-${r.key}`]}))}))
